use serde_json::Value;

fn solve(input: serde_json::Value) -> serde_json::Value {
    let mut result = Vec::new();
    for line in input.as_array() {
        let left = line.as_array();
        let right = line.as_array();
        let mut common_keys = Vec::new();
        for key in left.iter() {
            for value in right.iter() {
                if key == value {
                    common_keys.push(key);
                }
            }
        }
        common_keys.sort_unstable();
        result.push(vec![key, left[0], right[0]]);
    }
    result
}

fn main() {
    // Example usage
    let input = serde_json::Value::from("{\"input\":[[[2,9],[1,4]],[[2,3],[3,8]]],"expected":[[2,9,3]]}]");
    let output = solve(input);
    println!("{:?}", output);
}
